-- U1 DESIGN PROPOSAL ONLY. Do not execute as a migration.
-- Operational learning data only; corpus and artifact bytes remain separate.
PRAGMA foreign_keys = ON;

CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY, name TEXT NOT NULL, checksum TEXT NOT NULL, applied_at TEXT NOT NULL);
CREATE TABLE idempotency_records(operation_id TEXT PRIMARY KEY, learner_id TEXT NOT NULL, command_kind TEXT NOT NULL, input_fingerprint TEXT NOT NULL, result_fingerprint TEXT, status TEXT NOT NULL CHECK(status IN ('STARTED','COMMITTED','FAILED')), created_at TEXT NOT NULL, completed_at TEXT, UNIQUE(operation_id,command_kind));

CREATE TABLE learner_identities(learner_id TEXT PRIMARY KEY, account_id TEXT, identity_source TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, schema_version INTEGER NOT NULL, UNIQUE(account_id));
CREATE TABLE product_profiles(learner_id TEXT PRIMARY KEY REFERENCES learner_identities(learner_id), profile_json TEXT NOT NULL, record_version INTEGER NOT NULL, authority_owner TEXT NOT NULL CHECK(authority_owner='A'), authority_source TEXT NOT NULL, updated_at TEXT NOT NULL, operation_id TEXT NOT NULL REFERENCES idempotency_records(operation_id));
CREATE TABLE product_context_revisions(revision_id TEXT PRIMARY KEY, learner_id TEXT NOT NULL REFERENCES learner_identities(learner_id), prior_revision_id TEXT REFERENCES product_context_revisions(revision_id), authority_source TEXT NOT NULL, change_json TEXT NOT NULL, schema_version INTEGER NOT NULL, created_at TEXT NOT NULL, operation_id TEXT NOT NULL REFERENCES idempotency_records(operation_id));

CREATE TABLE material_sources(source_id TEXT PRIMARY KEY, learner_id TEXT REFERENCES learner_identities(learner_id), source_kind TEXT NOT NULL, title TEXT NOT NULL, owner_publisher TEXT, privacy_scope TEXT NOT NULL, usage_scope TEXT NOT NULL, metadata_json TEXT NOT NULL DEFAULT '{}', schema_version INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE artifacts(artifact_id TEXT PRIMARY KEY, learner_id TEXT NOT NULL REFERENCES learner_identities(learner_id), material_source_id TEXT REFERENCES material_sources(source_id), mode TEXT NOT NULL, created_at TEXT NOT NULL, schema_version INTEGER NOT NULL);
CREATE TABLE artifact_versions(artifact_version_id TEXT PRIMARY KEY, artifact_id TEXT NOT NULL REFERENCES artifacts(artifact_id), parent_version_id TEXT REFERENCES artifact_versions(artifact_version_id), author_kind TEXT NOT NULL CHECK(author_kind IN ('LEARNER','TEACHER','AI','SYSTEM','SOURCE')), original_text TEXT, content_sha256 TEXT, immutable INTEGER NOT NULL CHECK(immutable=1), created_at TEXT NOT NULL, operation_id TEXT NOT NULL REFERENCES idempotency_records(operation_id));
CREATE TABLE artifact_objects(object_id TEXT PRIMARY KEY, learner_id TEXT NOT NULL REFERENCES learner_identities(learner_id), artifact_version_id TEXT NOT NULL REFERENCES artifact_versions(artifact_version_id), relative_path TEXT NOT NULL, sha256 TEXT NOT NULL, byte_length INTEGER NOT NULL, mime_type TEXT NOT NULL, storage_state TEXT NOT NULL, privacy_scope TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(artifact_version_id,sha256));
CREATE TABLE artifact_spans(span_id TEXT PRIMARY KEY, artifact_version_id TEXT NOT NULL REFERENCES artifact_versions(artifact_version_id), region TEXT NOT NULL, text TEXT NOT NULL, confidence TEXT NOT NULL, location_json TEXT, alternatives_json TEXT NOT NULL DEFAULT '[]', extractor_id TEXT NOT NULL, extractor_version TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE source_confirmations(confirmation_id TEXT PRIMARY KEY, artifact_version_id TEXT NOT NULL REFERENCES artifact_versions(artifact_version_id), span_id TEXT REFERENCES artifact_spans(span_id), event_type TEXT NOT NULL, observed_text TEXT NOT NULL, confirmed_text TEXT NOT NULL, learner_id TEXT NOT NULL REFERENCES learner_identities(learner_id), created_at TEXT NOT NULL, operation_id TEXT NOT NULL REFERENCES idempotency_records(operation_id));

CREATE TABLE lesson_plan_snapshots(lesson_plan_id TEXT PRIMARY KEY, learner_id TEXT NOT NULL REFERENCES learner_identities(learner_id), target_ref TEXT NOT NULL, facet TEXT NOT NULL, plan_json TEXT NOT NULL, plan_version INTEGER NOT NULL, authority_owner TEXT NOT NULL CHECK(authority_owner='D'), created_at TEXT NOT NULL, immutable INTEGER NOT NULL CHECK(immutable=1));
CREATE TABLE lesson_sessions(session_id TEXT PRIMARY KEY, learner_id TEXT NOT NULL REFERENCES learner_identities(learner_id), lesson_plan_id TEXT NOT NULL REFERENCES lesson_plan_snapshots(lesson_plan_id), artifact_version_id TEXT REFERENCES artifact_versions(artifact_version_id), status TEXT NOT NULL, started_at TEXT NOT NULL, paused_at TEXT, ended_at TEXT, budget_minutes INTEGER NOT NULL, accumulated_paused_ms INTEGER NOT NULL DEFAULT 0, record_version INTEGER NOT NULL, updated_at TEXT NOT NULL);
CREATE UNIQUE INDEX one_active_session_per_learner ON lesson_sessions(learner_id) WHERE status IN ('SOURCE_REVIEW','READY','LEARNING','PAUSED');
CREATE TABLE session_lifecycle_events(event_id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES lesson_sessions(session_id), event_kind TEXT NOT NULL, occurred_at TEXT NOT NULL, payload_json TEXT NOT NULL DEFAULT '{}', operation_id TEXT NOT NULL REFERENCES idempotency_records(operation_id));
CREATE TABLE session_checkpoints(session_id TEXT PRIMARY KEY REFERENCES lesson_sessions(session_id), checkpoint_json TEXT NOT NULL, source_event_id TEXT NOT NULL REFERENCES session_lifecycle_events(event_id), record_version INTEGER NOT NULL, updated_at TEXT NOT NULL);

CREATE TABLE task_definitions(task_definition_version_id TEXT PRIMARY KEY, task_definition_id TEXT NOT NULL, owner_subsystem TEXT NOT NULL, definition_version INTEGER NOT NULL, definition_json TEXT NOT NULL, validation_status TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(task_definition_id,definition_version));
CREATE TABLE task_instances(task_instance_id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES lesson_sessions(session_id), task_definition_version_id TEXT REFERENCES task_definitions(task_definition_version_id), lesson_plan_id TEXT NOT NULL REFERENCES lesson_plan_snapshots(lesson_plan_id), target_ref TEXT NOT NULL, facet TEXT NOT NULL, task_family TEXT NOT NULL, prompt_or_source_ref TEXT, generation_run_id TEXT, created_at TEXT NOT NULL, operation_id TEXT NOT NULL REFERENCES idempotency_records(operation_id));
CREATE TABLE task_contract_snapshots(task_contract_id TEXT PRIMARY KEY, task_instance_id TEXT NOT NULL UNIQUE REFERENCES task_instances(task_instance_id), production_mode TEXT NOT NULL, support_before_response TEXT NOT NULL, answer_exposure TEXT NOT NULL, model_exposure TEXT NOT NULL, elicitation_condition TEXT NOT NULL, context_provenance TEXT NOT NULL, opportunity_present INTEGER NOT NULL, task_affordance_checked INTEGER NOT NULL, contract_json TEXT NOT NULL, contract_version INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE learner_actions(action_id TEXT PRIMARY KEY, learner_id TEXT NOT NULL REFERENCES learner_identities(learner_id), session_id TEXT REFERENCES lesson_sessions(session_id), task_instance_id TEXT REFERENCES task_instances(task_instance_id), action_kind TEXT NOT NULL, payload_json TEXT NOT NULL DEFAULT '{}', occurred_at TEXT NOT NULL, operation_id TEXT NOT NULL REFERENCES idempotency_records(operation_id));
CREATE TABLE block_instances(block_instance_id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES lesson_sessions(session_id), task_instance_id TEXT REFERENCES task_instances(task_instance_id), mechanism_id TEXT NOT NULL, mechanism_version TEXT NOT NULL, support_level TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE block_events(block_event_id TEXT PRIMARY KEY, block_instance_id TEXT NOT NULL REFERENCES block_instances(block_instance_id), learner_action_id TEXT REFERENCES learner_actions(action_id), event_kind TEXT NOT NULL, visible_before_response_json TEXT NOT NULL DEFAULT '[]', support_level TEXT NOT NULL, occurred_at TEXT NOT NULL, payload_json TEXT NOT NULL DEFAULT '{}', operation_id TEXT NOT NULL REFERENCES idempotency_records(operation_id));

CREATE TABLE learner_observations(observation_id TEXT PRIMARY KEY, learner_id TEXT NOT NULL REFERENCES learner_identities(learner_id), session_id TEXT REFERENCES lesson_sessions(session_id), artifact_version_id TEXT REFERENCES artifact_versions(artifact_version_id), task_instance_id TEXT REFERENCES task_instances(task_instance_id), observation_kind TEXT NOT NULL, observation_source TEXT NOT NULL, action TEXT NOT NULL, source_confidence TEXT NOT NULL, capability_evidence_allowed INTEGER NOT NULL, occurred_at TEXT NOT NULL, payload_json TEXT NOT NULL DEFAULT '{}', schema_version INTEGER NOT NULL, operation_id TEXT NOT NULL REFERENCES idempotency_records(operation_id));
CREATE TABLE evaluation_runs(evaluation_run_id TEXT PRIMARY KEY, learner_id TEXT NOT NULL REFERENCES learner_identities(learner_id), observation_id TEXT NOT NULL REFERENCES learner_observations(observation_id), task_contract_id TEXT REFERENCES task_contract_snapshots(task_contract_id), evaluator_id TEXT NOT NULL, evaluator_version TEXT NOT NULL, evaluator_provenance TEXT NOT NULL, authority_owner TEXT NOT NULL CHECK(authority_owner='K'), input_fingerprint TEXT NOT NULL, outcome TEXT NOT NULL, reason_codes_json TEXT NOT NULL, extension_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL, operation_id TEXT NOT NULL REFERENCES idempotency_records(operation_id));
CREATE TABLE evidence_candidates(candidate_id TEXT PRIMARY KEY, learner_id TEXT NOT NULL REFERENCES learner_identities(learner_id), observation_id TEXT NOT NULL REFERENCES learner_observations(observation_id), evaluation_run_id TEXT REFERENCES evaluation_runs(evaluation_run_id), task_contract_id TEXT REFERENCES task_contract_snapshots(task_contract_id), target_ref TEXT, facet TEXT, candidate_kind TEXT NOT NULL, evidence_polarity TEXT NOT NULL, production_mode TEXT NOT NULL, support_before_response TEXT NOT NULL, context_provenance TEXT NOT NULL, opportunity_present INTEGER, task_affordance_checked INTEGER NOT NULL, candidate_json TEXT NOT NULL, created_at TEXT NOT NULL, operation_id TEXT NOT NULL REFERENCES idempotency_records(operation_id));
CREATE TABLE evidence_admission_decisions(admission_id TEXT PRIMARY KEY, candidate_id TEXT NOT NULL UNIQUE REFERENCES evidence_candidates(candidate_id), decision TEXT NOT NULL CHECK(decision IN ('ADMITTED','REJECTED')), guard_id TEXT NOT NULL, guard_version TEXT NOT NULL, authority_owner TEXT NOT NULL CHECK(authority_owner IN ('C','K')), reason_codes_json TEXT NOT NULL, decided_at TEXT NOT NULL, operation_id TEXT NOT NULL REFERENCES idempotency_records(operation_id));
CREATE TABLE canonical_evidence(evidence_id TEXT PRIMARY KEY, learner_id TEXT NOT NULL REFERENCES learner_identities(learner_id), admission_id TEXT NOT NULL UNIQUE REFERENCES evidence_admission_decisions(admission_id), observation_id TEXT NOT NULL REFERENCES learner_observations(observation_id), target_ref TEXT NOT NULL, facet TEXT NOT NULL, dedup_key TEXT NOT NULL, authority_owner TEXT NOT NULL CHECK(authority_owner='C'), evidence_json TEXT NOT NULL, occurred_at TEXT NOT NULL, schema_version INTEGER NOT NULL, operation_id TEXT NOT NULL REFERENCES idempotency_records(operation_id), UNIQUE(learner_id,dedup_key));
CREATE INDEX evidence_by_learner_target ON canonical_evidence(learner_id,target_ref,facet,occurred_at);
CREATE TABLE learner_projection_cache(learner_id TEXT PRIMARY KEY REFERENCES learner_identities(learner_id), projection_json TEXT NOT NULL, projection_version INTEGER NOT NULL, evidence_high_watermark TEXT, rebuilt_at TEXT NOT NULL);
CREATE TABLE experience_read_model_cache(read_model_id TEXT PRIMARY KEY, learner_id TEXT NOT NULL REFERENCES learner_identities(learner_id), model_kind TEXT NOT NULL CHECK(model_kind IN ('TODAY','MY_ENGLISH','JOURNEY','LATEST_RESULT')), model_json TEXT NOT NULL, model_version INTEGER NOT NULL, source_high_watermark TEXT, rebuilt_at TEXT NOT NULL, UNIQUE(learner_id,model_kind));

CREATE TABLE teacher_context_snapshots(context_snapshot_id TEXT PRIMARY KEY, learner_id TEXT NOT NULL REFERENCES learner_identities(learner_id), session_id TEXT NOT NULL REFERENCES lesson_sessions(session_id), lesson_plan_id TEXT NOT NULL REFERENCES lesson_plan_snapshots(lesson_plan_id), task_instance_id TEXT REFERENCES task_instances(task_instance_id), decision_point_id TEXT NOT NULL, compiler_owner TEXT NOT NULL CHECK(compiler_owner='E'), compiler_version TEXT NOT NULL, context_json TEXT NOT NULL, source_fingerprint TEXT NOT NULL, compiled_at TEXT NOT NULL, operation_id TEXT NOT NULL REFERENCES idempotency_records(operation_id), UNIQUE(session_id,decision_point_id,source_fingerprint));
CREATE TABLE model_runs(model_run_id TEXT PRIMARY KEY, context_snapshot_id TEXT NOT NULL REFERENCES teacher_context_snapshots(context_snapshot_id), provider TEXT NOT NULL, model TEXT NOT NULL, prompt_version TEXT NOT NULL, schema_version TEXT NOT NULL, status TEXT NOT NULL, request_fingerprint TEXT NOT NULL, started_at TEXT NOT NULL, completed_at TEXT, error_code TEXT, extension_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE model_proposals(proposal_id TEXT PRIMARY KEY, model_run_id TEXT NOT NULL REFERENCES model_runs(model_run_id), proposal_json TEXT NOT NULL, response_fingerprint TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE teacher_qualifications(qualification_id TEXT PRIMARY KEY, context_snapshot_id TEXT NOT NULL REFERENCES teacher_context_snapshots(context_snapshot_id), proposal_id TEXT REFERENCES model_proposals(proposal_id), result TEXT NOT NULL CHECK(result IN ('ACCEPTED','REJECTED','FALLBACK')), qualifier_owner TEXT NOT NULL CHECK(qualifier_owner='E'), qualifier_version TEXT NOT NULL, reason_codes_json TEXT NOT NULL, created_at TEXT NOT NULL, operation_id TEXT NOT NULL REFERENCES idempotency_records(operation_id));
CREATE TABLE qualified_teacher_decisions(decision_id TEXT PRIMARY KEY, qualification_id TEXT NOT NULL UNIQUE REFERENCES teacher_qualifications(qualification_id), learner_id TEXT NOT NULL REFERENCES learner_identities(learner_id), session_id TEXT NOT NULL REFERENCES lesson_sessions(session_id), lesson_plan_id TEXT NOT NULL REFERENCES lesson_plan_snapshots(lesson_plan_id), decision_point_id TEXT NOT NULL, mechanism_id TEXT NOT NULL, authority_owner TEXT NOT NULL CHECK(authority_owner='E'), decision_json TEXT NOT NULL, created_at TEXT NOT NULL, operation_id TEXT NOT NULL REFERENCES idempotency_records(operation_id), UNIQUE(session_id,decision_point_id));
CREATE TABLE experience_contracts(experience_contract_id TEXT PRIMARY KEY, decision_id TEXT NOT NULL UNIQUE REFERENCES qualified_teacher_decisions(decision_id), authority_owner TEXT NOT NULL CHECK(authority_owner='N'), contract_json TEXT NOT NULL, contract_version INTEGER NOT NULL, created_at TEXT NOT NULL, operation_id TEXT NOT NULL REFERENCES idempotency_records(operation_id));
CREATE TABLE experience_executions(execution_id TEXT PRIMARY KEY, experience_contract_id TEXT NOT NULL REFERENCES experience_contracts(experience_contract_id), session_id TEXT NOT NULL REFERENCES lesson_sessions(session_id), effect TEXT NOT NULL, executed_at TEXT NOT NULL, operation_id TEXT NOT NULL REFERENCES idempotency_records(operation_id), UNIQUE(experience_contract_id,operation_id));
CREATE TABLE teaching_moves(teaching_move_id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES lesson_sessions(session_id), block_instance_id TEXT REFERENCES block_instances(block_instance_id), decision_id TEXT NOT NULL REFERENCES qualified_teacher_decisions(decision_id), mechanism_id TEXT NOT NULL, mechanism_version TEXT NOT NULL, authority_owner TEXT NOT NULL CHECK(authority_owner='F'), support_level TEXT NOT NULL, occurred_at TEXT NOT NULL, operation_id TEXT NOT NULL REFERENCES idempotency_records(operation_id));
CREATE TABLE treatment_responses(treatment_response_id TEXT PRIMARY KEY, teaching_move_id TEXT NOT NULL REFERENCES teaching_moves(teaching_move_id), observation_id TEXT REFERENCES learner_observations(observation_id), evaluation_run_id TEXT REFERENCES evaluation_runs(evaluation_run_id), outcome TEXT NOT NULL, occurred_at TEXT NOT NULL, extension_json TEXT NOT NULL DEFAULT '{}', operation_id TEXT NOT NULL REFERENCES idempotency_records(operation_id));

CREATE TABLE generation_runs(generation_run_id TEXT PRIMARY KEY, learner_id TEXT REFERENCES learner_identities(learner_id), session_id TEXT REFERENCES lesson_sessions(session_id), model_run_id TEXT REFERENCES model_runs(model_run_id), usage_context TEXT NOT NULL, input_lineage_json TEXT NOT NULL, validation_status TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE reencounter_schedules(schedule_id TEXT PRIMARY KEY, learner_id TEXT NOT NULL REFERENCES learner_identities(learner_id), target_ref TEXT NOT NULL, facet TEXT NOT NULL, schedule_kind TEXT NOT NULL, due_at TEXT, source_evidence_ids_json TEXT NOT NULL, status TEXT NOT NULL, schedule_version INTEGER NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE local_outbox(outbox_id TEXT PRIMARY KEY, learner_id TEXT NOT NULL REFERENCES learner_identities(learner_id), operation_id TEXT NOT NULL REFERENCES idempotency_records(operation_id), aggregate_kind TEXT NOT NULL, aggregate_id TEXT NOT NULL, event_kind TEXT NOT NULL, payload_json TEXT NOT NULL, created_at TEXT NOT NULL, sync_status TEXT NOT NULL DEFAULT 'LOCAL_ONLY', UNIQUE(operation_id,event_kind,aggregate_id));
CREATE TABLE migration_runs(migration_run_id TEXT PRIMARY KEY, source_kind TEXT NOT NULL, source_key TEXT NOT NULL, source_fingerprint TEXT, started_at TEXT NOT NULL, completed_at TEXT, accepted_count INTEGER NOT NULL DEFAULT 0, rejected_count INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL, report_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE deletion_tombstones(tombstone_id TEXT PRIMARY KEY, learner_id TEXT NOT NULL, deletion_scope TEXT NOT NULL, created_at TEXT NOT NULL, operation_id TEXT NOT NULL, completed_at TEXT);
